INSERT INTO `fa_support` (`id`, `type`, `title`, `content`, `lang`, `weigh`, `status`, `createtime`, `updatetime`) VALUES (1, 'faq', '入金はどのくらいで反映されますか？', '銀行振込は営業日30分以内、暗号資産はネットワーク承認後に反映されます。', 'ja', 100, 'normal', 1793172140, 1793172140);
INSERT INTO `fa_support` (`id`, `type`, `title`, `content`, `lang`, `weigh`, `status`, `createtime`, `updatetime`) VALUES (2, 'faq', 'How long does a withdrawal take?', 'Bank withdrawals are processed within 1 business day. Crypto withdrawals depend on network confirmation.', 'en', 99, 'normal', 1793172140, 1793172140);
INSERT INTO `fa_support` (`id`, `type`, `title`, `content`, `lang`, `weigh`, `status`, `createtime`, `updatetime`) VALUES (3, 'faq', '充值多久到账？', '银行卡充值一般在 30 分钟内到账；加密货币需等待链上确认。', 'zh', 98, 'normal', 1793172140, 1793172140);
INSERT INTO `fa_support` (`id`, `type`, `title`, `content`, `lang`, `weigh`, `status`, `createtime`, `updatetime`) VALUES (4, 'notice', 'システムメンテナンスのお知らせ', '毎週日曜 03:00-04:00 はシステムメンテナンスのため取引を停止します。', 'ja', 97, 'normal', 1793172140, 1793172140);
